The approach is a greedy, per-balloon plan: each balloon in turn picks the altitude sequence that maximizes the score added on top of the coverage already claimed by earlier balloons.

**State space.** A balloon's state is (altitude, row, col). With R, C, A up to 1000 this is far too large for a full DP, so I restrict to what can be reached.

**Per-balloon planning.**
- Reachable states are stored as a sparse layer per turn, with at most A·(reachable cells) entries per layer.
- At each turn, a state at altitude a moves to altitude a+d for d in {-1, 0, 1} (within 1..A), then moves by the wind vector at the new altitude.
- Only the best value per state is kept in a hash map, and a back-pointer is stored for reconstruction.
- The total state count can still blow up (up to about 1e6 states per layer, times 1000 turns, times 1000 balloons).

**Cheaper approximation.** I use beam search per balloon: the top K states per turn, with K small (about 30), keyed by (altitude, r, c). Cost is B·T·K·3 ≈ 1000·1000·30·3 = 9e7 transitions, and each needs a gain evaluation.

**Gain evaluation.** For a position (r, c) at turn t, the gain is the number of target cells within radius V that are not yet covered at turn t.
- Targets are bucketed by row, so a query scans targets in rows r-V..r+V.
- To keep this cheap, I precompute a list of targets for each row and test each with the distance formula.
- L ≤ 1000, so the worst case is 1000 checks per query, which is too slow at 9e7 queries.
- Fix: cache the gain per (t, r, c) lazily in a hash map? That is also costly.
- Instead I reduce K to about 6 and cap the work with a time check, because the total work is bounded by the clock. Balloons are planned until time runs out (about 8 s). Any balloon not planned stays on the ground with all zeros, which is valid.

**Beam scoring.** Value = accumulated gain. Ties are broken by a heuristic: distance to the nearest target, which I skip for simplicity. Because a beam of 6 with pure greedy gain gets stuck when no target is near, I add a small potential: negative distance to the nearest target, computed per row and column using a coarse scan over the targets, weighted lightly. This is cheap enough only if limited to the beam candidates, so I compute it once per candidate over at most 1000 targets, only when the gain is 0.

**Time guard.** The loop checks the clock per balloon. Balloon planning is cut off when the budget is exceeded. Unplanned balloons output zeros.

**Output.** An answer matrix of T×B, initialised to 0. After planning, the beam's best path is reconstructed and its altitude deltas are written in. Lost balloons follow the same rule: once off the grid the state is dead, and the remaining deltas are 0, which is valid.

```cpp
#include <bits/stdc++.h>
using namespace std;
int R,C,A,L,V,B,T,rs,cs;
vector<int> wr,wc;
vector<pair<int,int>> tg;
vector<vector<char>> cov;
vector<vector<int>> rowT;
int gain(int t,int r,int c){
    int g=0;
    for(int rr=max(0,r-V);rr<=min(R-1,r+V);rr++)
        for(int id:rowT[rr]){
            if(cov[t][id])continue;
            int dc=abs(c-tg[id].second);dc=min(dc,C-dc);
            int dr=r-rr;
            if(dr*dr+dc*dc<=V*V)g++;
        }
    return g;
}
void mark(int t,int r,int c){
    for(int rr=max(0,r-V);rr<=min(R-1,r+V);rr++)
        for(int id:rowT[rr]){
            int dc=abs(c-tg[id].second);dc=min(dc,C-dc);
            int dr=r-rr;
            if(dr*dr+dc*dc<=V*V)cov[t][id]=1;
        }
}
struct S{int a,r,c;long long v;int par;int d;};
int main(){
    auto st=chrono::steady_clock::now();
    scanf("%d %d %d %d %d %d %d %d %d",&R,&C,&A,&L,&V,&B,&T,&rs,&cs);
    tg.resize(L);rowT.assign(R,{});
    for(int i=0;i<L;i++){scanf("%d %d",&tg[i].first,&tg[i].second);rowT[tg[i].first].push_back(i);}
    wr.resize((size_t)A*R*C);wc.resize((size_t)A*R*C);
    for(size_t i=0;i<(size_t)A*R*C;i++)scanf("%d %d",&wr[i],&wc[i]);
    cov.assign(T+1,vector<char>(L,0));
    vector<vector<signed char>> ans(T,vector<signed char>(B,0));
    const int K=6;
    for(int b=0;b<B;b++){
        double el=chrono::duration<double>(chrono::steady_clock::now()-st).count();
        if(el>7.0)break;
        vector<vector<S>> lay(T+1);
        lay[0].push_back({0,rs,cs,0,-1,0});
        for(int t=1;t<=T;t++){
            vector<S> cand;
            for(int i=0;i<(int)lay[t-1].size();i++){
                S&s=lay[t-1][i];
                for(int d=-1;d<=1;d++){
                    int na=s.a+d;
                    if(na<0||na>A)continue;
                    if(s.a==0&&d<0)continue;
                    if(s.a>0&&na<1)continue;
                    int nr=s.r,nc=s.c;
                    if(na>=1){
                        size_t k=((size_t)(na-1)*R+s.r)*C+s.c;
                        nr=s.r+wr[k];
                        if(nr<0||nr>=R)continue;
                        nc=((s.c+wc[k])%C+C)%C;
                    }
                    long long v=s.v;
                    if(na>=1){
                        int g=gain(t,nr,nc);
                        v+=g*1000;
                        if(g==0){
                            int best=1<<30;
                            for(auto&p:tg){
                                int dc=abs(nc-p.second);dc=min(dc,C-dc);
                                best=min(best,abs(nr-p.first)+dc);
                            }
                            v-=min(best,999);
                        }
                    }
                    cand.push_back({na,nr,nc,v,i,d});
                }
            }
            sort(cand.begin(),cand.end(),[](const S&x,const S&y){
                if(x.v!=y.v)return x.v>y.v;
                if(x.a!=y.a)return x.a<y.a;
                if(x.r!=y.r)return x.r<y.r;
                return x.c<y.c;});
            for(auto&s:cand){
                bool dup=false;
                for(auto&q:lay[t])if(q.a==s.a&&q.r==s.r&&q.c==s.c){dup=true;break;}
                if(dup)continue;
                lay[t].push_back(s);
                if((int)lay[t].size()>=K)break;
            }
            if(lay[t].empty()){
                for(int u=t+1;u<=T;u++)lay[u].clear();
                break;
            }
        }
        int bi=-1;
        long long bv=-1;
        for(int i=0;i<(int)lay[T].size();i++)if(lay[T][i].v>bv){bv=lay[T][i].v;bi=i;}
        if(bi<0)continue;
        int idx=bi;
        for(int t=T;t>=1;t--){
            S&s=lay[t][idx];
            ans[t-1][b]=s.d;
            if(s.a>=1)mark(t,s.r,s.c);
            idx=s.par;
        }
    }
    string out;
    for(int t=0;t<T;t++){
        for(int b=0;b<B;b++){
            out+=to_string((int)ans[t][b]);
            out+=(b+1<B?' ':'\n');
        }
    }
    fputs(out.c_str(),stdout);
}
